// Original foundation-level scenarios; never official exam questions.
const SECURITY_EXAM=[
 ['A temporary contractor needs to read one project folder. Which access should you grant?', ['Administrator access','Read access to that folder only','A shared owner account','Access to every department'],1,'Least privilege limits permissions to the work required.'],
 ['Which login combines two different authentication factors?', ['Password and PIN','Two security questions','Password and a hardware key','Two passwords'],2,'A password is something you know; a hardware key is something you have.'],
 ['An urgent email claims to be from IT and asks you to approve an unexpected MFA prompt. What should you do?', ['Approve it quickly','Reply with your password','Disable MFA','Verify independently and report the request'],3,'Use a known, trusted channel rather than the contact information in the suspicious message.'],
 ['A stolen laptop contains encrypted files. What does the encryption primarily protect?', ['Confidentiality','Availability of power','Screen resolution','The laptop from theft'],0,'Encryption protects readable data from someone who lacks the key.'],
 ['A downloaded file has a different hash from the trusted publisher’s hash. What does this indicate?', ['The file is necessarily safe','The bytes differ from the expected file','The file is encrypted','The download is faster'],1,'A mismatch signals a change or corruption. A hash comparison alone does not establish the cause.'],
 ['A workstation uses a firewall, MFA, endpoint monitoring, and tested backups. What approach is this?', ['Single sign-on','Obscurity alone','Defense in depth','Removing redundancy'],2,'Complementary layers reduce reliance on any one control.'],
 ['Ransomware is spreading from a workstation. Following the response plan, which action supports containment?', ['Isolate the affected workstation from the network','Delete every log','Ignore it until morning','Share its password'],0,'Isolation helps limit spread while responders investigate and preserve evidence.'],
 ['A backup job reports success. What is the strongest next check of recoverability?', ['Rename the backup','Count the icons','Assume success proves recovery','Perform and verify a test restoration'],3,'Restoration testing checks whether data can actually be recovered.'],
 ['During incident response, what should be recorded?', ['Nothing until all evidence is deleted','Actions, times, findings, and evidence handling','Only the final password','Only the attacker’s claimed identity'],1,'Accurate records support investigation and recovery.'],
 ['After containing an incident, responders remove its underlying malware and persistence. Which activity is this?', ['Authentication','Recovery testing','Eradication','Provisioning'],2,'Eradication removes the cause; recovery returns systems to safe operation.'],
 ['A service should accept only required network traffic. Which control directly enforces that?', ['Firewall rules','A longer monitor cable','A file naming convention','An extra keyboard'],0,'Firewalls permit or deny traffic according to configured rules.'],
 ['Files are restored after ransomware. Why must investigation continue?', ['Restoration makes logs unnecessary','Backups always stop theft','The incident can never recur','Data may have been stolen and the entry point may remain'],3,'Ransomware may involve data theft, and unresolved causes can allow another compromise.']
];
function examConfig(r=2){
 if(r===2)return {bank:SECURITY_EXAM,url:'https://www.pearsonvue.com/us/en/comptia.html',label:'Official CompTIA exam scheduling'};
 if(r===3)return {bank:CLOUD_EXAMS[3],url:'https://aws.amazon.com/certification/certified-cloud-practitioner/',label:'Official AWS certification information'};
 if(r===4)return {bank:CLOUD_EXAMS[4],url:'https://learn.microsoft.com/en-us/credentials/certifications/azure-fundamentals/',label:'Official Microsoft certification information'};
 return null;
}
function examUnlocked(s=state,r=2){return !!examConfig(r)&&realms[r].chapters.every((_,c)=>s.done.includes(`${r}-${c}`)&&s.read.includes(`${r}-${c}`));}
function examState(r=2,s=state){return r===2?s.securityExam:s.cloudExams?.[r];}
function setExamState(r,e){if(r===2)state.securityExam=e;else{state.cloudExams??={};state.cloudExams[r]=e;}}
function validateExam(s){
 if(s.cloudExams!==undefined&&(!s.cloudExams||typeof s.cloudExams!=='object'||Array.isArray(s.cloudExams)||Object.keys(s.cloudExams).some(r=>!['3','4'].includes(r))))throw Error('Invalid cloud exams');
 for(const r of [2,3,4]){const e=examState(r,s);if(e==null)continue;const bank=examConfig(r).bank;
 if(!examUnlocked(s,r)||e.version!==1||!Array.isArray(e.answers)||e.answers.length!==bank.length||e.answers.some(a=>a!==null&&(!Number.isInteger(a)||a<0||a>3))||!Number.isInteger(e.index)||e.index<0||e.index>=bank.length||typeof e.submitted!=='boolean'||(e.submitted&&e.answers.includes(null)))throw Error('Invalid exam');}
}
function examGate(r=2){const config=examConfig(r),e=examState(r);if(!config)return '';return `<article class="paper"><h2>${realms[r].cert} final trial</h2><p>Finish all ${realms[r].chapters.length} lessons and encounters in this realm to unlock a ${config.bank.length}-question foundations practice exam. Your answers save as you go. Score 80% or higher to pass this trial.</p><button class="primary" ${examUnlocked(state,r)?'':'disabled'} onclick="openExam(${r})">${e?(e.submitted?'View exam results':'Resume practice exam'):'Take the practice exam'}</button>${examUnlocked(state,r)?'':'<p>Locked: read each lesson in this realm and defeat its encounter.</p>'}<p>This short course and trial do not cover the full certification syllabus. The official exam is booked separately with the certification provider.</p><a class="study-link" href="${config.url}" target="_blank" rel="noopener">${config.label} ↗</a></article>`;}
function openExam(r=2){if(!examUnlocked(state,r))return toast('Complete all lessons and encounters in this realm first.');if(state.battle)return toast('Finish or flee your battle first.');if(!examState(r))setExamState(r,{version:1,index:0,answers:Array(examConfig(r).bank.length).fill(null),submitted:false});go('exam',r);}
function activeExamRealm(){return route.view==='exam'?(route.r??2):2;}
function examAnswer(i){const e=examState(activeExamRealm());if(route.view!=='exam'||!e||e.submitted||!Number.isInteger(i)||i<0||i>3)return;e.answers[e.index]=i;save();examScreen();}
function examMove(i){const r=activeExamRealm(),e=examState(r);if(route.view!=='exam'||!e||!Number.isInteger(i)||i<0||i>=examConfig(r).bank.length)return;e.index=i;save();examScreen();}
function submitExam(){const e=examState(activeExamRealm());if(route.view!=='exam'||!e||e.submitted||e.answers.includes(null))return toast('Answer every question before submitting.');e.submitted=true;save();examScreen();}
function retryExam(){const r=activeExamRealm();if(route.view!=='exam'||!examState(r)?.submitted)return;setExamState(r,null);openExam(r);}
function examScreen(){
 const r=activeExamRealm(),e=examState(r);if(!examUnlocked(state,r)||!e)return go('realm',r);
 const bank=examConfig(r).bank,score=e.answers.reduce((n,a,i)=>n+(a===bank[i][2]?1:0),0),percent=Math.round(score/bank.length*100);
 if(e.submitted){app.innerHTML=`<section class="lesson"><button class="back" onclick="go('realm',${r})">← ${realms[r].cert} realm</button><div class="eyebrow">${realms[r].cert} foundations practice exam</div><h1>${score/bank.length>=0.8?'Trial passed!':'Review, then try again.'}</h1><h2>${score}/${bank.length} correct · ${percent}%</h2><p>Your result is saved. Passing this trial does not award an official certification or establish full exam readiness.</p><button class="primary" onclick="retryExam()">Retake practice exam</button><h2>Your answer review</h2>${bank.map((q,i)=>`<article class="paper"><h3>${i+1}. ${q[0]}</h3><p>${e.answers[i]===q[2]?'✓ Correct':'Review this topic'} · Your answer: ${q[1][e.answers[i]]}</p><p><strong>Correct answer: ${q[1][q[2]]}</strong></p><p>${q[3]}</p></article>`).join('')}${examGate(r)}</section>`;return;}
 const q=bank[e.index];app.innerHTML=`<section class="lesson"><button class="back" onclick="go('realm',${r})">← Save & leave exam</button><div class="eyebrow">${realms[r].cert} foundations · Final trial</div><h1>Question ${e.index+1} of ${bank.length}</h1><p>${e.answers.filter(a=>a!==null).length} answered · No time limit · Answers and explanations appear after submission.</p><article class="paper"><h2>${q[0]}</h2><div class="answers">${q[1].map((a,i)=>`<button aria-pressed="${e.answers[e.index]===i}" style="${e.answers[e.index]===i?'outline:3px solid #8a6535':''}" onclick="examAnswer(${i})">${e.answers[e.index]===i?'✓ ':''}${a}</button>`).join('')}</div></article><div class="actions"><button ${e.index===0?'disabled':''} onclick="examMove(${e.index-1})">← Previous</button><button ${e.index===bank.length-1?'disabled':''} onclick="examMove(${e.index+1})">Next →</button><button class="primary" ${e.answers.includes(null)?'disabled':''} onclick="submitExam()">Submit exam</button></div><p>Use Previous and Next to review your choices before submitting.</p></section>`;
}
